_RANK_TRAJECTORY_ERROR = (
    "report must be a frontier_rank_attribution JSON output"
)


class _RankTrajectoryNumber(Decimal):
    """Marker for a canonical fixed-six-decimal number token."""


def _rank_pick(value: object, error: str) -> tuple[str, ...]:
    """Validate one pick: a non-empty list of distinct intervention
    kinds (members of ``_INTERVENTION_KINDS``) in strictly ascending
    order, returned as a tuple."""
    if not isinstance(value, list) or not value or any(
        kind not in _INTERVENTION_KINDS for kind in value
    ):
        raise ValueError(error)
    if any(
        value[position] >= value[position + 1]
        for position in range(len(value) - 1)
    ):
        raise ValueError(error)
    return tuple(value)


def _rank_trajectory_parse_int(value: str) -> int:
    return int(value)


def _coerce_plan_pick(value: object, error: str) -> tuple[str, ...]:
    """Validate one user-supplied pick and return it as a tuple.

    A pick may be given as a tuple or lifted verbatim from a report's
    ``pick`` JSON array (a list); either way it must be a non-empty
    sequence of distinct intervention kinds (``green``, ``roof`` or
    ``material``) in strictly ascending order.
    """
    if not isinstance(value, (list, tuple)) or not value or any(
        not isinstance(kind, str) or kind not in _INTERVENTION_KINDS
